import java.lang.reflect.*;

interface Calc { int add(int x, int y); }
class CalcImpl implements Calc { public int add(int x, int y) { return x + y; } }
class AroundHandler implements InvocationHandler {
    private Object target;
    AroundHandler(Object t) { target = t; }
    public Object invoke(Object p, Method m, Object[] args) throws Throwable {
        long s = System.nanoTime();
        System.out.println("[around] enter " + m.getName());
        Object r = m.invoke(target, args);
        long e = System.nanoTime();
        System.out.println("[around] exit " + m.getName());
        return r;
    }
}
public class Main {
    public static void main(String[] a) throws Exception {
        Calc proxy = (Calc) Proxy.newProxyInstance(Calc.class.getClassLoader(),
            new Class[]{Calc.class}, new AroundHandler(new CalcImpl()));
        System.out.println("result=" + proxy.add(3, 4));
    }
}
